{
  "apiVersion": 1,
  "type": "docs.detail",
  "package": "@astryxdesign/cli",
  "data": {
    "name": "illustrations",
    "description": "Illustration guidelines for empty states, onboarding flows, and feature highlights.",
    "category": "foundations",
    "keywords": [
      "empty state"
    ],
    "title": "Illustrations",
    "sections": [
      {
        "id": "when-to-use",
        "title": "When to Use",
        "package": "@astryxdesign/cli",
        "category": "foundations",
        "content": [
          {
            "type": "prose",
            "text": "Consistent illustration usage reinforces brand identity and helps users understand context at a glance. Use illustrations in these contexts:"
          },
          {
            "type": "table",
            "headers": [
              "Context",
              "Examples"
            ],
            "rows": [
              [
                "Empty states",
                "No data, first-time experience, search with no results"
              ],
              [
                "Onboarding",
                "Welcome screens, feature introduction, setup wizards"
              ],
              [
                "Feature highlights",
                "New feature announcements, upgrade prompts"
              ],
              [
                "Error states",
                "Permission denied, not found, service unavailable"
              ]
            ]
          }
        ]
      },
      {
        "id": "guidelines",
        "title": "Guidelines",
        "package": "@astryxdesign/cli",
        "category": "foundations",
        "content": [
          {
            "type": "list",
            "style": "do",
            "items": [
              "Keep illustrations consistent in style across the product.",
              "Use simple, flat illustrations that work in both light and dark mode.",
              "Size illustrations proportionally to the container, typically 120–240px.",
              "Place illustrations centered with supporting text below."
            ]
          },
          {
            "type": "list",
            "style": "dont",
            "items": [
              "Mix illustration styles from different sources.",
              "Use illustrations as decoration without purpose."
            ]
          }
        ]
      },
      {
        "id": "placement",
        "title": "Placement",
        "package": "@astryxdesign/cli",
        "category": "foundations",
        "content": [
          {
            "type": "prose",
            "text": "For an empty state, pass the illustration to the `icon` slot of `EmptyState`, which centers it above the title and description. Typical illustration sizes range from 120px for inline empty states to 240px for full-page onboarding screens. Always pair the illustration with a title and a description that says what to do next."
          },
          {
            "type": "code",
            "lang": "tsx",
            "code": "<EmptyState\n  icon={<img src=\"/illustrations/empty-search.svg\" alt=\"\" width={200} height={200} />}\n  title=\"No results found\"\n  description=\"Try adjusting your search or filters.\"\n/>",
            "label": "Empty state with illustration"
          }
        ]
      }
    ],
    "links": {
      "up": "astryx docs foundations",
      "previous": "astryx docs icons",
      "next": "astryx docs motion"
    }
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
